384	// SummarizeSource folds a per-branch view of the fact store into the
385	// source manifest recorded under sources.facts in the brain manifest.
386	func SummarizeSource(now time.Time, byBranch map[string][]factmerge.Record, chunksScanned, chunksDistilled, proposals int, warnings []string) *bmanifest.FactSource {
387		source := &bmanifest.FactSource{
388			GeneratedAt:     now,
389			TaxonomyPath:    TaxonomyPath,
390			Proposals:       proposals,
391			ChunksScanned:   chunksScanned,
392			ChunksDistilled: chunksDistilled,
393			Warnings:        append([]string(nil), warnings...),
394			ByKind:          map[string]int{},
395		}
396		branches := make([]string, 0, len(byBranch))
397		for branch := range byBranch {
398			branches = append(branches, branch)
399		}
400		sort.Strings(branches)
401		source.Branches = branches
402		for _, branch := range branches {
403			for _, record := range byBranch[branch] {
404				// A stored line carrying no id is not a fact (see IsFactRecord): it
405				// cannot be fetched, recalled, verified or superseded. Counting it
406				// here is how a damaged store re-declared its own damage as healthy
407				// on the next `remember` or `refresh`, and it is what the integrity
408				// cross-check compares against.
409				if !IsFactRecord(record) {
410					continue
411				}
412				if record.Status == factmerge.StatusCandidate {
413					// A staged candidate is not a published memory yet: counting it
414					// into Facts would inflate every surface after a crashed run,
415					// while hiding it would make the staged work invisible. Its own
416					// counter keeps both honest until the next distill reconciles it.
417					source.PendingReconcile++
418					continue
419				}
420				source.Facts++
421				switch record.Origin {
422				case OriginDistilled:
423					source.Distilled++
424				case OriginAuthored:
425					source.Authored++
426				case OriginImported:
427					// Without this bucket an imported fact raises the total and no
428					// line item, so the origins visibly do not sum to the count and
429					// nothing explains the difference.
430					source.Imported++
431				}
432				if record.Status == factmerge.StatusSuperseded {
433					source.Superseded++
434				}
435				// by_kind counts only active facts, matching what recall/tree surface
436				// (superseded/retracted facts are not retrievable), so the histogram
437				// answers "what kinds can I recall" rather than paralleling Facts.
438				if record.Status == factmerge.StatusActive {
439					source.ByKind[KindOrInferred(record)]++
440				}
441				for _, anchor := range record.Provenance {
442					if anchor.Verified {
443						source.Verified++
444					} else {
445						source.Unsigned++
446					}
447				}
448			}
449		}
450		return source
451	}
