453	// MissingStoreWarningForBranch scopes retrieval warnings to the store read.
454	func MissingStoreWarningForBranch(brainDir string, source *bmanifest.FactSource, branch string) string {
455		integrity := Inspect(brainDir, source)
456		switch integrity.Mode {
457		case DefectMissing:
458			for _, missing := range integrity.Missing {
459				if missing == branch {
460					return MissingStoreWarning([]string{branch})
461				}
462			}
463			return ""
464		case DefectUnreadable:
465			for _, unreadable := range integrity.Unreadable {
466				if unreadable == branch {
467					return integrity.Warning()
468				}
469			}
470			return ""
471		default:
472			// Aggregate count discrepancies cannot be assigned to one branch.
473			return integrity.Warning()
474		}
475	}
